// Leer historial SQLite + construir prompt con contexto
const { execSync } = require('child_process');

const chatId  = String($input.first().json.message.chat.id);
const mensaje = String($input.first().json.message.text || '');

// Escapar para heredoc Python
const msgEsc = mensaje
  .replace(/\\/g, '\\\\')
  .replace(/'/g, "'\\''")
  .replace(/"/g, '\\"');

const pyCode = `
import sqlite3, json, os
from datetime import datetime

DB      = '/data/data/com.termux/files/home/bot_history.db'
chat_id = '${chatId}'
mensaje = '${msgEsc}'

conn = sqlite3.connect(DB)
conn.execute('''CREATE TABLE IF NOT EXISTS historial (
    id      INTEGER PRIMARY KEY AUTOINCREMENT,
    chat_id TEXT NOT NULL,
    rol     TEXT NOT NULL,
    content TEXT NOT NULL,
    modelo  TEXT,
    fecha   TEXT
)''')
conn.execute('CREATE INDEX IF NOT EXISTS idx_chat ON historial(chat_id)')
conn.commit()

rows = conn.execute(
    'SELECT rol, content FROM historial WHERE chat_id=? ORDER BY id DESC LIMIT 8',
    (chat_id,)
).fetchall()
conn.close()

historial = list(reversed(rows))
lineas = []
for rol, content in historial:
    prefijo = 'Usuario' if rol == 'user' else 'Bot'
    lineas.append(f'{prefijo}: {content}')

contexto = '\\n'.join(lineas)
prompt = f'{contexto}\\nUsuario: {mensaje}\\nBot:' if contexto else mensaje

print(json.dumps({
    'chat_id': chat_id,
    'mensaje': mensaje,
    'prompt': prompt
}, ensure_ascii=False))
`;

let stdout = '';
let stderr = '';
try {
  stdout = execSync(
    '/data/data/com.termux/files/usr/bin/python3 -c "' + pyCode.replace(/"/g, '\\"') + '"',
    { timeout: 15000, encoding: 'utf8' }
  );
} catch (e) {
  stderr = e.message || String(e);
}

return [{ json: { stdout: stdout.trim(), stderr: stderr.trim(), chatId, mensaje } }];

const raw = $input.first().json;
const stdout = raw.stdout || '{}';
const stderr = raw.stderr || '';

if (!stdout && stderr) {
  return [{ json: {
    chat_id: raw.chatId || '',
    mensaje: raw.mensaje || '',
    prompt: raw.mensaje || '',
    _error: 'execSync_failed: ' + stderr
  }}];
}

let data;
try {
  data = JSON.parse(stdout);
} catch(e) {
  data = {
    chat_id: raw.chatId || '',
    mensaje: raw.mensaje || '',
    prompt: raw.mensaje || '',
    _error: 'parse_failed: ' + stdout
  };
}

// Sanitizar prompt — quitar saltos de línea reales, escapar comillas dobles
data.prompt = (data.prompt || '')
  .replace(/[\r\n]+/g, ' ')
  .replace(/"/g, "'");

return [{ json: data }];

