// Extraer respuesta limpia de Ollama
const input = $input.first().json;
let respuesta = '';

if (input.response) {
  respuesta = String(input.response).trim();
} else if (input.body && input.body.response) {
  respuesta = String(input.body.response).trim();
} else {
  respuesta = JSON.stringify(input);
}

respuesta = respuesta
  .replace(/^Bot:\s*/i, '')
  .replace(/^Assistant:\s*/i, '')
  .trim();

if (!respuesta) respuesta = 'No pude generar respuesta. Intenta de nuevo.';

const prev = $('Parsear contexto').first().json;
return [{ json: {
  chat_id: prev.chat_id,
  mensaje: prev.mensaje,
  respuesta
}}];

// Guardar turno usuario + bot en SQLite
const { execSync } = require('child_process');

const input     = $input.first().json;
const chatId    = String(input.chat_id || '');
const mensaje   = String(input.mensaje   || '').replace(/\\/g, '\\\\').replace(/'/g, "'\\''")
 const respuesta = String(input.respuesta || '').replace(/\\/g, '\\\\').replace(/'/g, "'\\''")

const pyCode = `
import sqlite3
from datetime import datetime

DB   = '/data/data/com.termux/files/home/bot_history.db'
chat = '${chatId}'
user = '${mensaje}'
bot  = '${respuesta}'
now  = datetime.now().strftime('%Y-%m-%d %H:%M:%S')

conn = sqlite3.connect(DB)
conn.execute(
    'INSERT INTO historial (chat_id, rol, content, modelo, fecha) VALUES (?,?,?,?,?)',
    (chat, 'user', user, None, now)
)
conn.execute(
    'INSERT INTO historial (chat_id, rol, content, modelo, fecha) VALUES (?,?,?,?,?)',
    (chat, 'assistant', bot, 'qwen2.5:3b', now)
)
conn.commit()
conn.close()
print('guardado')
`;

let stdout = '';
let stderr = '';
try {
  stdout = execSync(
    '/data/data/com.termux/files/usr/bin/python3 -c "' + pyCode.replace(/"/g, '\\"') + '"',
    { timeout: 10000, encoding: 'utf8' }
  );
} catch (e) {
  stderr = e.message || String(e);
}

return [{ json: {
  chat_id: input.chat_id,
  respuesta: input.respuesta,
  sqlite_ok: stdout.trim() === 'guardado',
  sqlite_err: stderr.trim()
}}];
